// With placeholders
console.log(curriedAdd(_, 2, 3)(1)); // 6
console.log(curriedAdd(1, _, 3)(2)); // 6
console.log(curriedAdd(_, _, 3)(_, 1)(3)); // 7;`},{type:"heading",text:"Testcase - 2"},{type:"code",language:"javascript",value:`const greet = (greeting, name, punctuation) => \`\${greeting}, \${name}\${punctuation}\`;

const sayHello = curry(greet)("Hello");
console.log(sayHello("Alice")("!")); // "Hello, Alice!"

