promise.then(null, (error) => {
  console.error("Called from then method", error);
});

// "Called from then method" "Error 404"

promise.catch((error) => {
  console.error("Called from catch method", error);
});

// "Called from catch method" "Error 404";`},{type:"paragraph",text:"As you can notice multiple handlers can be assigned on the same promise and then will execute in the order of assignment."},{type:"paragraph",text:"The catch block can also be extended further using .then()."},{type:"code",language:"javascript",value:`promise
